catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   //Type appropriate comment here, and begin script below
   if (!/^\d{10}$/.test(newValue)) {
        g_form.addInfoMessage('Phone number must be exactly 10 digits.');
		g_form.clearValue('phone_number');
    }

    // Check if it starts with 9, 8, 7, or 6
    if (!/^[9876]/.test(newValue)) {
        g_form.addInfoMessage('Phone number must start with 9, 8, 7, or 6.');
		g_form.clearValue('phone_number');
    }

    // Check if it contains more than 3 consecutive 0s
    if (/0{4,}/.test(newValue)) {
        g_form.addInfoMessage('Phone number cannot contain more than three consecutive zeros.');
		g_form.clearValue('phone_number');
    }

}
